const http = require('http');

const maskPort = (host) => String(host).replace(/:\d+$/, ':PORT');

const server = http.createServer((req, res) => {
  console.log('== 服务端看到的请求 ==');
  console.log('请求行   : ' + req.method + ' ' + req.url + ' HTTP/1.1');
  console.log('Host     : ' + maskPort(req.headers.host));
  console.log('X-Demo   : ' + req.headers['x-demo']);
  console.log('Content-Type : ' + req.headers['content-type']);
  console.log('');
  res.writeHead(201, {
    'Content-Type': 'application/json; charset=utf-8',
    'Location': '/v1/users/42',
  });
  res.end(JSON.stringify({ id: 42, name: 'cppcat' }));
});

server.listen(0, '127.0.0.1', () => {
  const port = server.address().port;
  const req = http.request(
    {
      host: '127.0.0.1',
      port,
      path: '/v1/users',
      method: 'POST',
      headers: {
        'X-Demo': 'hello',
        'Accept': 'application/json',
        'Content-Type': 'application/json',
      },
    },
    (res) => {
      console.log('== 客户端看到的响应 ==');
      console.log('状态行   : HTTP/1.1 ' + res.statusCode + ' ' + res.statusMessage);
      console.log('Content-Type : ' + res.headers['content-type']);
      console.log('Location : ' + res.headers['location']);
      let body = '';
      res.on('data', (c) => (body += c));
      res.on('end', () => {
        console.log('响应体   : ' + body);
        console.log('');
        console.log('说明：Host / Content-Length 由客户端库自动添加；');
        console.log('      状态码与 Location 由服务端通过 writeHead 决定。');
        server.close();
      });
    }
  );
  req.end(JSON.stringify({ name: 'cppcat' }));
});
